import { createHmac } from "node:crypto";
export default async function f({ headers, secret }, ctx) {
  const h = Object.fromEntries(Object.entries(headers).map(([k, v]) => [k.toLowerCase(), v]));
  const expected = createHmac("sha256", secret)
      .update(String(h["request-id"] || "") + "\n" + String(h.direction || ""))
      .digest("hex"),
    sig = String(h["x-signature"] || "");
  let diff = sig.length ^ expected.length;
  for (let i = 0; i < expected.length; i++)
    diff |= (sig.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
  if (
    !secret ||
    diff ||
    !/^[-A-Za-z0-9_]{8,128}$/.test(h["request-id"] || "") ||
    !["Check-In", "Check-Out"].includes(h.direction)
  )
    throw Error("Invalid attendance event");
  const key = "attendance:" + h["request-id"],
    s = await ctx.state.get(key);
  if (s) throw Error("Inspect previous attendance event " + key);
  await ctx.state.set(key, { phase: "pending" });
  let d = new Date();
  return {
    key,
    direction: h.direction,
    date: d.toISOString().slice(0, 10),
    time: d.toISOString().slice(11, 16),
  };
}

