export default async function f(_, ctx) {
  const key = "attendance:spreadsheet",
    s = await ctx.state.get(key);
  if (s) throw Error("Inspect previous spreadsheet creation");
  await ctx.state.set(key, { phase: "pending" });
  return { ok: true };
}

