export default async function f({ id, sheets }, ctx) {
  const title = sheets?.[0]?.properties?.title;
  if (!id || !title) throw Error("Inspect spreadsheet creation");
  await ctx.state.set("attendance:spreadsheet", { phase: "created", id, title });
  return { id, title, range: "'" + title.replaceAll("'", "''") + "'!A1:C1" };
}

