export default async function f({ existing, created, title }, ctx) {
  if (created) {
    await ctx.state.set("attendance:spreadsheet", { phase: "done", id: created, title });
    return { id: created, range: "'" + title.replaceAll("'", "''") + "'!A:C" };
  }
  const s = await ctx.state.get("attendance:spreadsheet");
  const name = s?.id === existing ? s.title : "Worklog";
  return { id: existing, range: "'" + name.replaceAll("'", "''") + "'!A:C" };
}

